<script setup lang="ts">
import { computed,onMounted,onUnmounted,ref } from 'vue';
import { invoke,isTauri } from '@tauri-apps/api/core';
import { ElMessage } from 'element-plus';
import { ArrowUpRight,ArrowDownLeft,Cpu,MemoryStick,HardDrive,SlidersHorizontal,ArrowUpRight as OpenIcon,Pause,Play,Power,ChevronRight } from 'lucide-vue-next';
import AppLogo from './components/AppLogo.vue';
import MiniChart from './components/MiniChart.vue';
import TraySettings from './components/TraySettings.vue';
import {preferences,loadPreferences,savePreferences,subscribePreferences} from './preferences';
import {monitorSnapshot as snapshot,monitorHistory as history,monitorError,startMonitor,stopMonitor,formatBytes,formatRate} from './monitor';
const tab=ref<'overview'|'settings'>('overview'),native=isTauri(),busy=ref(false),error=ref('');
let disposed=false,unlisten:(()=>void)|undefined;
const memory=computed(()=>{const s=snapshot.value;return s?.memory_total&&s.memory_used!=null?s.memory_used/s.memory_total*100:null;});
const cpuValues=computed(()=>history.value.map(s=>s.cpu_percent));
const memoryValues=computed(()=>history.value.map(s=>s.memory_total&&s.memory_used!=null?s.memory_used/s.memory_total*100:null));
const downValues=computed(()=>history.value.map(s=>s.network_down??null));
const upValues=computed(()=>history.value.map(s=>s.network_up??null));
const diskUsed=computed(()=>snapshot.value?.disk_total&&snapshot.value.disk_available!=null?Math.max(0,100-snapshot.value.disk_available/snapshot.value.disk_total*100):0);
const percent=(value:number|null|undefined)=>value==null?'—':`${value.toFixed(0)}%`;
async function open(route:string){if(!native)return;try{await invoke('open_main_page',{route});}catch(cause){ElMessage.error(String(cause));}}
async function toggle(){if(busy.value)return;busy.value=true;try{await savePreferences({monitor_enabled:!preferences.monitor_enabled});}catch(cause){ElMessage.error(String(cause));}finally{busy.value=false;}}
async function quit(){if(!native)return;try{await invoke('quit_app');}catch(cause){ElMessage.error(String(cause));}}
function keydown(event:KeyboardEvent){if(event.key==='Escape'&&native)void invoke('hide_tray_panel').catch(cause=>ElMessage.error(String(cause)));}
onMounted(async()=>{window.addEventListener('keydown',keydown);try{const stop=await subscribePreferences();if(disposed){stop();return;}unlisten=stop;await loadPreferences();if(!disposed)startMonitor();}catch(cause){error.value=String(cause);}});
onUnmounted(()=>{disposed=true;unlisten?.();stopMonitor();window.removeEventListener('keydown',keydown);});
</script>
<template>
  <main class="tray-panel">
    <header class="tray-header"><div class="tray-brand"><AppLogo :size="42"/><div><strong>AppClear</strong><span><i :class="{paused:!preferences.monitor_enabled}"/>{{ !native?'界面预览':preferences.monitor_enabled?'本机资源，尽在眼前':'采样已暂停' }}</span></div></div><button class="icon-button" :aria-label="tab==='overview'?'自定义菜单栏':'返回资源总览'" :class="{active:tab==='settings'}" @click="tab=tab==='overview'?'settings':'overview'"><SlidersHorizontal :size="17"/></button></header>
    <div class="tray-tabs" role="tablist" aria-label="菜单栏面板"><button role="tab" :aria-selected="tab==='overview'" :class="{selected:tab==='overview'}" @click="tab='overview'">资源总览</button><button role="tab" :aria-selected="tab==='settings'" :class="{selected:tab==='settings'}" @click="tab='settings'">自定义</button></div>
    <div class="tray-scroll">
      <p v-if="error||monitorError" class="tray-warning" role="alert">{{ error||monitorError }}</p>
      <div v-if="tab==='overview'" role="tabpanel" aria-label="资源总览" class="overview">
        <div class="overview-label"><span>此刻，本机状态</span><button :disabled="!native||busy" @click="toggle"><Pause v-if="preferences.monitor_enabled" :size="11"/><Play v-else :size="11"/>{{ preferences.monitor_enabled?'暂停':'继续' }}</button></div>
        <p v-if="!preferences.monitor_enabled" class="paused-note">以下保留上次采样</p>
        <section class="network-card"><div class="card-heading"><span>网络流量</span><small :title="snapshot?.network_interface">{{ preferences.tray.network_interface==='auto'?'自动 · 物理网卡':preferences.tray.network_interface }}</small></div><div class="network-columns"><article class="down"><span><ArrowDownLeft :size="14"/>下载</span><strong>{{ formatRate(snapshot?.network_down,preferences.tray.rate_unit==='bits') }}</strong><MiniChart v-if="preferences.tray.show_sparklines" :values="downValues" label="近期下载速度"/></article><article class="up"><span><ArrowUpRight :size="14"/>上传</span><strong>{{ formatRate(snapshot?.network_up,preferences.tray.rate_unit==='bits') }}</strong><MiniChart v-if="preferences.tray.show_sparklines" :values="upValues" label="近期上传速度"/></article></div></section>
        <div class="resource-grid"><article class="resource-card cpu"><div class="card-heading"><span>CPU</span><Cpu :size="15"/></div><strong :class="{high:(snapshot?.cpu_percent||0)>85}">{{ percent(snapshot?.cpu_percent) }}</strong><MiniChart v-if="preferences.tray.show_sparklines" :values="cpuValues" :max="100" label="近期 CPU 使用率"/><small>全机平均使用率</small></article><article class="resource-card memory" title="内存百分比不等同于内存压力"><div class="card-heading"><span>内存</span><MemoryStick :size="15"/></div><strong>{{ percent(memory) }}</strong><MiniChart v-if="preferences.tray.show_sparklines" :values="memoryValues" :max="100" label="近期内存使用率"/><small>{{ formatBytes(snapshot?.memory_used) }} / {{ formatBytes(snapshot?.memory_total) }}</small></article></div>
        <section class="disk-card"><HardDrive :size="18"/><div><span>磁盘可用</span><strong>{{ formatBytes(snapshot?.disk_available) }}</strong></div><span class="disk-chart" :style="{'--used':`${diskUsed}%`}" aria-hidden="true"/><div class="disk-bar"><span :style="{width:`${diskUsed}%`}"/></div></section>
        <div class="quick-actions"><button :disabled="!native" @click="open('/clean')"><span>清理空间</span><ChevronRight :size="16"/></button><button :disabled="!native" @click="open('/monitor')"><span>详细监控</span><ChevronRight :size="16"/></button></div>
        <p class="sample-note">{{ !native?'浏览器预览 · 未连接本机数据':!snapshot?'等待首个采样间隔…':`每 ${preferences.tray.interval_ms/1000} 秒更新 · ${new Date(snapshot.sampled_at).toLocaleTimeString('zh-CN',{hour12:false})}` }}</p>
      </div>
      <div v-else role="tabpanel" aria-label="自定义菜单栏"><TraySettings/></div>
    </div>
    <footer class="tray-footer"><button :disabled="!native" @click="open('/')">打开 AppClear<OpenIcon :size="12"/></button><button :disabled="!native" aria-label="退出 AppClear" @click="quit"><Power :size="12"/>退出</button></footer>
  </main>
</template>
<style scoped>
