-rgb),.08),transparent 80%)}.card-heading{display:flex;justify-content:space-between;align-items:center;color:var(--text-muted);font-size:10px;gap:12px}.card-heading small{font-size:9px;color:var(--text-faint);overflow:hidden;white-space:nowrap;text-overflow:ellipsis;max-width:160px}.network-columns{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:16px}.network-columns article>span{display:flex;align-items:center;gap:4px;font-size:10px}.down{color:var(--accent)}.up{color:var(--cyan)}.network-columns strong{display:block;white-space:nowrap;font-size:20px;font-weight:550;letter-spacing:-.6px;font-variant-numeric:tabular-nums;margin:8px 0 10px;color:var(--text)}.resource-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:10px 0}.resource-card{border:1px solid var(--line);border-radius:13px;background:var(--surface-subtle);padding:13px 13px 11px}.resource-card strong{display:block;font-size:29px;letter-spacing:-1.1px;font-weight:500;font-variant-numeric:tabular-nums;margin:12px 0 6px;color:var(--text)}.cpu{color:var(--accent)}.memory{color:var(--cyan)}.resource-card .high{color:var(--warning)}.resource-card small{display:block;color:var(--text-faint);font-size:9px;margin-top:6px;white-space:nowrap}.disk-card{border:1px solid var(--line);border-radius:13px;display:flex;align-items:center;gap:11px;padding:13px;position:relative;overflow:hidden}.disk-card>svg{color:var(--text-faint)}.disk-card>div>span{font-size:9px;display:block;color:var(--text-faint)}.disk-card strong{display:block;font-size:16px;font-weight:500;margin-top:4px;font-variant-numeric:tabular-nums}.disk-chart{margin-left:auto;width:32px;height:32px;border-radius:50%;background:conic-gradient(var(--accent) var(--used),var(--accent-soft) 0);position:relative}.disk-chart:after{content:'';position:absolute;inset:5px;background:var(--surface);border-radius:50%}.disk-bar{display:none}.quick-actions{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:13px}.quick-actions button{display:flex;align-items:center;justify-content:space-between;gap:4px;background:none;border:0;color:var(--text-secondary);text-align:left;padding:8px 0;font-size:11px}.quick-actions small{display:block;font-size:9px;color:var(--text-faint);margin-top:5px}.quick-actions svg{color:var(--text-faint)}.quick-actions button:hover{color:var(--accent)}.sample-note{font-size:9px;color:var(--text-faint);line-height:1.8;margin:7px 0 0;text-align:center}.sample-note span{display:block;font-size:8px;opacity:.8}.tray-warning{font-size:11px;color:var(--warning);background:var(--warning-soft);padding:10px;border-radius:8px;overflow-wrap:anywhere}.tray-footer{flex-shrink:0;padding:12px 21px;border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;background:var(--surface-subtle)}.tray-footer button{border:0;background:none;display:flex;align-items:center;gap:5px;color:var(--text-muted);font-size:10px;padding:2px 0}.tray-footer button:hover{color:var(--accent)}
.network-card{padding:12px 13px 6px}.network-columns{margin-top:10px}.network-columns strong{margin:6px 0;font-size:19px}.network-columns :deep(svg[role="img"]){height:24px}.resource-card{padding:12px 12px 10px}.resource-card strong{margin:9px 0 5px;font-size:27px}.resource-card :deep(svg[role="img"]){height:24px}.resource-card small{margin-top:4px}.disk-card{padding:11px 12px}.quick-actions{margin-top:7px}.quick-actions button{padding:7px 0}.sample-note{margin-top:5px}
</style>
